import math

# ---------------------------------------------------------------------------
# Constants (match official Orbit Wars env)
# ---------------------------------------------------------------------------
BOARD_SIZE = 100.0
CENTER = 50.0
SUN_RADIUS = 10.0
ROTATION_RADIUS_LIMIT = 50.0
MAX_SPEED = 6.0
_LOG1000 = math.log(1000.0)
_SPEED_RANGE = MAX_SPEED - 1.0

# ---------------------------------------------------------------------------
# Geometry & Physics
# ---------------------------------------------------------------------------

def dist(p1, p2):
    """Euclidean distance between two objects with x, y attributes."""
    return math.hypot(p1.x - p2.x, p1.y - p2.y)

def fleet_speed(ships):
    """Official Orbit Wars fleet speed formula."""
    if ships <= 1:
        return 1.0
    if ships >= 1000:
        return MAX_SPEED
    ratio = math.log(ships) / _LOG1000
    return min(1.0 + _SPEED_RANGE * (ratio ** 1.5), MAX_SPEED)

def fleet_eta(src, tgt, ships):
    """Estimated turns to arrival (dist / speed, min 1)."""
    d = math.hypot(src.x - tgt.x, src.y - tgt.y)
    s = fleet_speed(ships)
    return max(1.0, d / s)

def path_crosses_sun(x1, y1, x2, y2):
    """True if the line segment from (x1,y1) to (x2,y2) intersects the sun."""
    dx, dy = x2 - x1, y2 - y1
    l2 = dx * dx + dy * dy
    if l2 < 1e-12:
        return math.hypot(x1 - CENTER, y1 - CENTER) < SUN_RADIUS
    t = max(0.0, min(1.0, ((CENTER - x1) * dx + (CENTER - y1) * dy) / l2))
    proj_x = x1 + t * dx
    proj_y = y1 + t * dy
    return math.hypot(proj_x - CENTER, proj_y - CENTER) < SUN_RADIUS

def is_orbiting(planet):
    """True if planet is within the rotation radius limit."""
    px = planet.x if hasattr(planet, "x") else planet['x']
    py = planet.y if hasattr(planet, "y") else planet['y']
    return math.hypot(px - CENTER, py - CENTER) < ROTATION_RADIUS_LIMIT

def predict_planet_pos(planet, angular_vel, steps):
    """Predict planet position after N steps of rotation."""
    if not is_orbiting(planet) or steps <= 0:
        px = planet.x if hasattr(planet, "x") else planet['x']
        py = planet.y if hasattr(planet, "y") else planet['y']
        return px, py

    px = planet.x if hasattr(planet, "x") else planet['x']
    py = planet.y if hasattr(planet, "y") else planet['y']
    dx, dy = px - CENTER, py - CENTER
    r = math.hypot(dx, dy)
    cur_theta = math.atan2(dy, dx)
    new_theta = cur_theta + angular_vel * steps
    return CENTER + r * math.cos(new_theta), CENTER + r * math.sin(new_theta)

def predict_fleet_target(fleet, planets, angular_vel, max_steps=200):
    """
    Predict which planet a fleet is targeting by simulating paths forward.
    Returns (planet_id, eta) or (None, None).
    """
    # handle object, dict, and tuple/list formats
    if isinstance(fleet, dict):
        fx, fy = fleet['x'], fleet['y']
        fa = fleet['angle']
        f_ships = fleet['ships']
    elif hasattr(fleet, "x"):
        fx, fy = fleet.x, fleet.y
        fa = fleet.angle
        f_ships = fleet.ships
    else:
        fx, fy = fleet[2], fleet[3]
        fa = fleet[4]
        f_ships = fleet[6]

    # Legacy prediction (forgiving angular cone)
    # This model is 'blind' to complex orbital intercepts but
    # provides the strategic aggression needed for high-level play.
    dx_sun, dy_sun = fx - 50, fy - 50
    dist_to_sun = math.hypot(dx_sun, dy_sun)
    if dist_to_sun < SUN_RADIUS + 5: # Close to sun
        return -2, 5

    f_speed = fleet_speed(f_ships)
    for p in planets:
        if isinstance(p, dict):
            px, py, pid = p['x'], p['y'], p['id']
        elif hasattr(p, "x"):
            px, py, pid = p.x, p.y, p.id
        else:
            px, py, pid = p[2], p[3], p[0]

        dx, dy = px - fx, py - fy
        angle_to_p = math.atan2(dy, dx)
        diff = abs(angle_to_p - fa)
        while diff > math.pi: diff = abs(diff - 2 * math.pi)

        if diff < 0.15: # Cone filter
            dist = math.hypot(dx, dy)
            eta = dist / max(f_speed, 0.1)
            return pid, int(eta)

    return None, None

def fleets_targeting(planet, fleets, angular_vel=0.0, planets=None, turns_ahead=None):
    """Filter fleets that appear to be moving toward the given planet."""
    results = []
    p_id = planet.id if hasattr(planet, "id") else planet[0]

    for f in fleets:
        if angular_vel == 0 or planets is None:
            # Fallback to static angle check
            desired = math.atan2(planet.y - f.y, planet.x - f.x)
            diff = abs(math.remainder(f.angle - desired, 2 * math.pi))
            if diff < 0.1:
                if turns_ahead is not None:
                    d = math.hypot(f.x - planet.x, f.y - planet.y)
                    f_ships = f.ships if hasattr(f, "ships") else f[6]
                    eta = d / fleet_speed(f_ships)
                    if eta > turns_ahead:
                        continue
                results.append(f)
        else:
            # Use dynamic prediction
            target_id, eta = predict_fleet_target(f, planets, angular_vel)
            if target_id == p_id:
                if turns_ahead is not None and eta > turns_ahead:
                    continue
                results.append(f)
    return results

def is_fleet_threatening(fleet, planet, threshold_deg=15.0):
    """
    Trajectory analysis: Returns True if fleet is moving toward the planet
    within a specified angular cone.
    """
    if isinstance(fleet, dict):
        fx, fy, fa = fleet['x'], fleet['y'], fleet['angle']
    elif hasattr(fleet, "x"):
        fx, fy, fa = fleet.x, fleet.y, fleet.angle
    else:
        fx, fy, fa = fleet[2], fleet[3], fleet[4]

    if isinstance(planet, dict):
        px, py = planet['x'], planet['y']
    elif hasattr(planet, "x"):
        px, py = planet.x, planet.y
    else:
        px, py = planet[2], planet[3]

    dx, dy = px - fx, py - fy
    d = math.hypot(dx, dy)
    if d < 1e-6: return True

    # Dot product approach
    cos_fa, sin_fa = math.cos(fa), math.sin(fa)
    dot = (dx/d) * cos_fa + (dy/d) * sin_fa

    # threshold_deg = 45 -> cos(45) = 0.707
    threshold_cos = math.cos(math.radians(threshold_deg))
    return dot > threshold_cos

# ---------------------------------------------------------------------------
# Advanced Forecasts (for compatibility with existing tests)
# ---------------------------------------------------------------------------

def forecast_planet_ownership(planet, incoming_fleets, turns):
    """Estimate (owner, ships) after N turns considering incoming fleets."""
    # Simple model: resolve production, then combat
    ships = float(planet.ships)
    if planet.owner != -1:
        ships += planet.production * turns

    # Resolve fleets in arrival order
    arrivals = []
    for f in incoming_fleets:
        d = math.hypot(f.x - planet.x, f.y - planet.y)
        eta = d / fleet_speed(f.ships)
        if eta <= turns:
            arrivals.append((eta, f))

    arrivals.sort(key=lambda x: x[0])

    current_owner = planet.owner
    current_ships = ships

    for _, f in arrivals:
        if f.owner == current_owner:
            current_ships += f.ships
        else:
            current_ships -= f.ships
            if current_ships < 0:
                current_owner = f.owner
                current_ships = -current_ships

    return (current_owner, current_ships)

def project_net_garrison(planet, incoming_fleets, turns, perspective_owner):
    """Relative ship count for perspective_owner after N turns."""
    owner, ships = forecast_planet_ownership(planet, incoming_fleets, turns)
    return ships if owner == perspective_owner else -ships
import numpy as np

# Physical Constants
CENTER = 50.0
SUN_RADIUS = 7.0
MAX_SPEED = 6.0
ANGULAR_VEL = 0.01

@jax.jit
def get_fleet_speed(ships):
    return jnp.maximum(1.0, MAX_SPEED - jnp.log1p(ships))

@jax.jit
def point_seg_dist_sq(px, py, x1, y1, x2, y2):
    dx, dy = x2 - x1, y2 - y1
    l2 = dx*dx + dy*dy
    t = jnp.where(l2 < 1e-12, 0.0, jnp.clip(((px - x1) * dx + (py - y1) * dy) / l2, 0.0, 1.0))
    proj_x = x1 + t * dx
    proj_y = y1 + t * dy
    return (px - proj_x)**2 + (py - proj_y)**2

@jax.jit
def jax_simulate_step(planets, fleets, metadata, pos_table):
    """
    planets: (N, 10) [id, owner, x, y, radius, ships, prod, ix, iy, comet]
    fleets: (M, 8) [id, owner, x, y, angle, from_pid, ships, active]
    metadata: (3,) [ang_vel, step, next_id]
    """
    ang_vel, step, next_id = metadata[:3]
    new_step = step + 1

    # 1. Production
    owners = planets[:, 1]
    prod = planets[:, 6]
    ships = planets[:, 5]
    new_ships = ships + jnp.where(owners != -1, prod, 0.0)
    planets = planets.at[:, 5].set(new_ships)

    # 2. Movement
    f_active = fleets[:, 7] > 0.5
    f_ships = fleets[:, 6]
    f_speed = get_fleet_speed(f_ships)
    f_angle = fleets[:, 4]

    ox, oy = fleets[:, 2], fleets[:, 3]
    nx = ox + jnp.where(f_active, jnp.cos(f_angle) * f_speed, 0.0)
    ny = oy + jnp.where(f_active, jnp.sin(f_angle) * f_speed, 0.0)

    # Sun / OOB Check
    dist_sun_sq = point_seg_dist_sq(CENTER, CENTER, ox, oy, nx, ny)
    killed = (nx < 0) | (nx > 100) | (ny < 0) | (ny > 100) | (dist_sun_sq < SUN_RADIUS**2)

    # Planet Collision
    # (M, N) distance matrix
    def dist_to_all_planets(fx, fy, fnx, fny):
        return jax.vmap(lambda px, py: point_seg_dist_sq(px, py, fx, fy, fnx, fny))(planets[:, 2], planets[:, 3])

    all_dists_sq = jax.vmap(dist_to_all_planets)(ox, oy, nx, ny)
    collision_mask = all_dists_sq < (planets[:, 4]**2) # (M, N)

    is_hit_any = jnp.any(collision_mask, axis=1)
    hit_planet_idx = jnp.argmax(collision_mask, axis=1)

    # Update Fleets
    new_f_active = fleets[:, 7] * (1.0 - killed.astype(jnp.float32)) * (1.0 - is_hit_any.astype(jnp.float32))
    fleets = fleets.at[:, 2].set(jnp.where(is_hit_any | killed, ox, nx))
    fleets = fleets.at[:, 3].set(jnp.where(is_hit_any | killed, oy, ny))
    fleets = fleets.at[:, 7].set(new_f_active)

    # 3. Rotation (Vectorized using O(1) lookup table)
    # Match the Numba rotation logic exactly
    step_idx = jnp.clip(new_step, 0, 499).astype(jnp.int32)
    p_ids = planets[:, 0].astype(jnp.int32)

    # Only rotate if not a comet (planets[:, 9] < 0.5)
    is_planet = planets[:, 9] < 0.5
    rot_x = pos_table[p_ids, step_idx, 0]
    rot_y = pos_table[p_ids, step_idx, 1]

    planets = planets.at[:, 2].set(jnp.where(is_planet, rot_x, planets[:, 2]))
    planets = planets.at[:, 3].set(jnp.where(is_planet, rot_y, planets[:, 3]))

    # 4. Combat Resolution (Numba-Parity Survivor Logic)
    combat_buffer = jnp.zeros((planets.shape[0], 4))
    f_owners = fleets[:, 1].astype(jnp.int32)
    f_hit_idx = hit_planet_idx.astype(jnp.int32)

    # Sum arrivals (only for players 0-3)
    f_is_player = (f_owners >= 0) & (f_owners <= 3)
    valid_f_owners = jnp.clip(f_owners, 0, 3)
    combat_buffer = combat_buffer.at[f_hit_idx, valid_f_owners].add(jnp.where(is_hit_any & f_is_player, fleets[:, 6], 0.0))

    # Find top attacker
    sorted_arrivals = jnp.sort(combat_buffer, axis=1)
    top1 = sorted_arrivals[:, 3]
    top2 = sorted_arrivals[:, 2]

    survivor_ships = top1 - top2
    survivor_owner = jnp.argmax(combat_buffer, axis=1).astype(jnp.float32)

    # Apply to planet
    p_owner = planets[:, 1]
    p_ships = planets[:, 5]

    is_same_owner = (p_owner == survivor_owner)
    new_ships_val = jnp.where(is_same_owner, p_ships + survivor_ships, p_ships - survivor_ships)

    # Handle capture
    owner_changed = (new_ships_val < 0)
    final_p_owner = jnp.where(owner_changed, survivor_owner, p_owner)
    final_p_ships = jnp.abs(new_ships_val)

    # Only update if someone arrived
    any_arrived = (top1 > 0)
    planets = planets.at[:, 1].set(jnp.where(any_arrived, final_p_owner, p_owner))
    planets = planets.at[:, 5].set(jnp.where(any_arrived, final_p_ships, p_ships))

    new_metadata = metadata.at[1].set(new_step)

    return planets, fleets, new_metadata


@partial(jax.jit, static_argnums=(4,))
def jax_simulate_batch(planets_batch, fleets_batch, metadata_batch, pos_table, n):
    """Run n steps for a batch of states using vmap and scan."""
    def step_fn(carry, _):
        p, f, m = carry
        # Vectorize across the batch dimension
        p_new, f_new, m_new = jax.vmap(jax_simulate_step, in_axes=(0, 0, 0, None))(p, f, m, pos_table)
        return (p_new, f_new, m_new), None

    (planets_batch, fleets_batch, metadata_batch), _ = jax.lax.scan(
        step_fn, (planets_batch, fleets_batch, metadata_batch), jnp.arange(n)
    )
    return planets_batch, fleets_batch, metadata_batch

@jax.jit
def jax_evaluate_single(planets, fleets, player_id, step, weights):
    """Vectorized evaluation of a single state."""
    pw, sw, tp, eb, urgency_alpha, intent_threshold, leader_penalty, centrality_weight, roi_threshold, peace_weight = weights

    p_owners = planets[:, 1]
    p_ships = planets[:, 5]
    p_prod = planets[:, 6]
    p_x, p_y = planets[:, 2], planets[:, 3]

    # 1. Identify Leader
    p_val = p_prod * pw + p_ships * sw

    def get_player_total(pid):
        return jnp.where(p_owners == pid, p_val, 0.0).sum()

    totals = jax.vmap(get_player_total)(jnp.arange(4.0))
    totals_masked = jnp.where(jnp.arange(4.0) == player_id, -1.0, totals)
    max_total = jnp.max(totals_masked)
    leader_id = jnp.argmax(totals_masked)

    is_leader_planet = (p_owners == leader_id)
    leader_prod_masked = jnp.where(is_leader_planet, p_prod, -1.0)
    best_leader_planet_idx = jnp.argmax(leader_prod_masked)

    has_leader = (max_total > 0.0)
    leader_pos_x = jnp.where(has_leader, p_x[best_leader_planet_idx], -100.0)
    leader_pos_y = jnp.where(has_leader, p_y[best_leader_planet_idx], -100.0)

    # 2. Planet Scores
    dist_center = jnp.sqrt((p_x - 50.0)**2 + (p_y - 50.0)**2)
    centrality = (75.0 - dist_center) / 75.0

    dx = p_x[:, None] - p_x[None, :]
    dy = p_y[:, None] - p_y[None, :]
    dist_matrix = jnp.sqrt(dx**2 + dy**2)

    is_mine = (p_owners == player_id)
    is_not_mine_all = (p_owners != player_id)

    dist_to_action = jnp.where(is_not_mine_all[None, :], dist_matrix, 100.0)
    min_dist_to_action = jnp.min(dist_to_action, axis=1)

    decay = jnp.maximum(0.1, 1.0 - (step / 500.0))
    urgency_penalty = p_prod * (min_dist_to_action * urgency_alpha) * decay

    hoard_ratio = p_ships / jnp.maximum(1.0, p_prod * 10.0)
    hoard_penalty = jnp.where(hoard_ratio > 1.0, (hoard_ratio - 1.0) * p_prod * 0.5, 0.0)

    # Gravity Shielding
    dist_sun_sq = jax.vmap(lambda px, py: point_seg_dist_sq(50.0, 50.0, px, py, leader_pos_x, leader_pos_y))(p_x, p_y)
    path_crosses_sun = dist_sun_sq < 7.0**2
    shield_bonus = jnp.where(has_leader & path_crosses_sun, p_prod * 10.0, 0.0)

    my_planet_score = p_ships * sw + p_prod * pw + centrality * centrality_weight + shield_bonus - urgency_penalty - hoard_penalty
    my_planet_total = jnp.where(is_mine, my_planet_score, 0.0).sum()

    enemy_base_val = p_ships * sw + p_prod * pw + centrality * centrality_weight
    is_leader = (p_owners == leader_id)
    penalty = jnp.where(is_leader, leader_penalty, peace_weight)
    enemy_planet_total = jnp.where((p_owners != -1) & ~is_mine, -enemy_base_val * penalty, 0.0).sum()

    remaining = 500.0 - step
    gain = p_prod * remaining
    neutral_val = p_prod * pw * eb * (remaining / 500.0)
    neutral_planet_total = jnp.where((p_owners == -1) & (gain > 50.0 * roi_threshold), neutral_val, 0.0).sum()

    # 3. Fleet Scores
    f_owners = fleets[:, 1]
    f_ships = fleets[:, 6]
    f_active = fleets[:, 7] > 0.5

    my_fleet_score = jnp.where(f_active & (f_owners == player_id), f_ships * sw * 1.05, 0.0).sum()
    f_penalty = jnp.where(f_owners == leader_id, leader_penalty, peace_weight)
    enemy_fleet_score = jnp.where(f_active & (f_owners != player_id) & (f_owners != -1), -f_ships * sw * f_penalty, 0.0).sum()

    total_score = my_planet_total + enemy_planet_total + neutral_planet_total + my_fleet_score + enemy_fleet_score
    return total_score

@jax.jit
def jax_evaluate_batch(planets_batch, fleets_batch, player_id, step_batch, weights):
    return jax.vmap(jax_evaluate_single, in_axes=(0, 0, None, 0, None))(
        planets_batch, fleets_batch, player_id, step_batch, weights
    )

def warm_up():
    """Enable X64, configure persistent XLA compilation cache, and compile exact shapes."""
    import os
    from jax import config

    # 1. Identify cache directory
    try:
        script_dir = os.path.dirname(os.path.abspath(__file__))
    except Exception:
        script_dir = os.path.abspath(".")

    cache_path = None

    # Check A: Flat jit_ files in script directory
    if os.path.exists(script_dir):
        try:
            if any(f.startswith("jit_") for f in os.listdir(script_dir)):
                cache_path = script_dir
        except Exception:
            pass

    # Check B: Flat jit_ files in current working directory
    if not cache_path and os.path.exists("."):
        try:
            if any(f.startswith("jit_") for f in os.listdir(".")):
                cache_path = os.path.abspath(".")
        except Exception:
            pass

    # Check C: jax_cache subdirectory in script directory
    if not cache_path:
        script_cache_dir = os.path.join(script_dir, "jax_cache")
        if os.path.exists(script_cache_dir):
            cache_path = script_cache_dir

    # Check D: jax_cache subdirectory in current working directory
    if not cache_path:
        cwd_cache_dir = os.path.abspath("jax_cache")
        if os.path.exists(cwd_cache_dir):
            cache_path = cwd_cache_dir

    # Check E: Fallback to home dev path
    if not cache_path:
        cache_path = os.path.join(os.path.expanduser("~"), ".gemini", "antigravity", "jax_cache")
        os.makedirs(cache_path, exist_ok=True)

    config.update("jax_compilation_cache_dir", cache_path)
    config.update("jax_persistent_cache_min_compile_time_secs", 0)
    config.update("jax_enable_x64", True)

    # MUST match exactly what's passed in main.py MCTS
    # We use 200 max_fleets instead of 1000 to massively speed up JAX CPU vectorization
    p = jnp.zeros((32, 100, 10), dtype=jnp.float64)
    f = jnp.zeros((32, 200, 8), dtype=jnp.float64)
    m = jnp.zeros((32, 4), dtype=jnp.float64)
    pos_table = jnp.zeros((100, 501, 2), dtype=jnp.float64)
    weights = jnp.zeros((10,), dtype=jnp.float64)

    try:
        # Pre-compile simulate step and batch evaluation with exact dimensions
        p_res, f_res, m_res = jax_simulate_batch(p, f, m, pos_table, 64)
        p_res.block_until_ready()

        rewards_res = jax_evaluate_batch(p, f, 0, m[:, 1], weights)
        rewards_res.block_until_ready()
        print(f"JAX Engine Warmup Complete. Cache resolved at {cache_path}")
    except Exception as e:
        print(f"JAX Warmup Failed: {e}")

if __name__ == "__main__":
    warm_up()

"""Fast Python forward model for Orbit Wars.

Implements simulate_step(state, actions) → new_state using plain Python +
NumPy, bypassing the kaggle-environments interpreter overhead.

Design goals:
  - Exact parity with the official interpreter for the common case
    (static planets, no comets). Comets use pre-computed paths stored on
    the GameState and are advanced the same way as the official env.
  - Pure Python / NumPy — no C extensions, no kaggle-environments import.
  - Immutable public API: simulate_step never mutates the input state.
  - Fast internal path: _simulate_step_mut mutates in-place (for MCTS rollouts).
  - Vectorised fleet movement using NumPy for the common N-fleets case.
  - __slots__ on hot dataclasses to cut per-object memory overhead.

Speed vs official env:
  Official env:   ~600 steps/s  (Python + IPC overhead through the
                                  full kaggle-environments pipeline)
  This model:    ~60,000–120,000 steps/s  (direct Python + NumPy)
  Numba model:   ~1,500,000+ steps/s    (compiled

Usage:

    # Build initial state from a Kaggle observation dict/Namespace
    state = GameState.from_obs(obs)

    # Simulate one step with agent actions (dict player_id → list of moves)
    next_state = simulate_step(state, actions={0: [[pid, angle, ships], ...]})

    # Fast N-step rollout (no action, for terminal-value estimation)
    final = simulate_n_steps(state, n=50)

    # MCTS-friendly mutable rollout (avoids copy overhead)
    clone = state.copy()
    _simulate_step_mut(clone, actions={})
"""


