THREAT_WEIGHT = 3.5
EARLY_EXPAND_BONUS = 10.0
URGENCY_ALPHA = 0.005
LEAD_TARGETING_PEACE_WEIGHT = 0.05
CENTRALITY_WEIGHT = 3.0
ROI_THRESHOLD = 0.8
LEADER_PENALTY = 1.0

# [Phase 7] Elite Refinement constants
SNIPE_TOLERANCE = 0.1 # Drift buffer (pixels)
COALITION_THRESHOLD = 2 # Unique enemies targeting us
TURTLE_GARRISON_MULT = 15.0 # Defensive floor when being teamed up

def _dist(p1, p2):
    return math.hypot(p1.x - p2.x, p1.y - p2.y)

def get_macro_candidates(state: GameState, player_id):
    planets = state.planets
    my_planets = [p for p in planets if p.owner == player_id]
    if not my_planets: return [[]]
    candidates = [[]]
    targets = [p for p in planets if p.owner != player_id and p.id not in state.comet_ids]

    # [Phase 7] Coalition Detection
    incoming_enemies = [f for f in state.fleets if f.owner != player_id]

    # Very aggressive expansion (v888 style)
    for s in sorted(my_planets, key=lambda p: p.ships, reverse=True)[:3]:
        # [Phase 7] Turtle Mode Check
        incoming_to_us = [f for f in incoming_enemies if is_fleet_threatening(f, s)]
        unique_attackers = len(set(f.owner for f in incoming_to_us))
        is_turtle = unique_attackers >= COALITION_THRESHOLD

        # [Phase 6] Frontier Dynamics: Baseline Garrison
        enemy_planets = [e for e in planets if e.owner != player_id and e.owner != -1]
        dist_to_enemy = min([_dist(s, e) for e in enemy_planets]) if enemy_planets else 1000.0
        frontier_mult = 4.0 if dist_to_enemy < 35 else 1.0

        # Garrison logic
        g_mult = TURTLE_GARRISON_MULT if is_turtle else frontier_mult
        safety = s.production * g_mult
        surplus = int(s.ships - safety)

        if surplus > 0:
            count = 0
            for t in sorted(targets, key=lambda p: _dist(s, p))[:5]:
                tx, ty = t.x, t.y
                if t.owner != -1:
                    dist = _dist(s, t)
                    eta_est = dist / 1.5
                    # [Phase 7] Drift-Aware Prediction
                    tx, ty = predict_planet_pos(t, state.angular_velocity, int(eta_est))
                    dx, dy = tx - s.x, ty - s.y
                    mag = math.hypot(dx, dy)
                    tx += (dx / mag) * SNIPE_TOLERANCE
                    ty += (dy / mag) * SNIPE_TOLERANCE

                if not path_crosses_sun(s.x, s.y, tx, ty):
                    angle = math.atan2(ty - s.y, tx - s.x)
                    if t.owner == -1:
                        # First principles fix: Only send what is needed to capture neutral planets
                        # plus a small buffer for drift/eta.
                        needed = int(t.ships) + 1
                        send = min(surplus, needed)
                        if send > 0:
                            candidates.append([[s.id, angle, send]])
                            count += 1
                    else:
                        # Full surplus for enemy planets
                        candidates.append([[s.id, angle, surplus]])
                        count += 1
    return candidates[:30]

class MCTSNode:
    def __init__(self, state, parent=None, action=None):
        self.state = state
        self.parent = parent
        self.action = action
        self.children = []
        self.visits = 0
        self.value = 0.0
        self.untried_actions = None

    def select_child(self):
        best_score = -float('inf')
        best_child = None
        for child in self.children:
            expl = C_PARAM * math.sqrt(math.log(self.visits + 1) / (child.visits + 1e-6))
            score = (child.value / (child.visits + 1e-6)) + expl
            if score > best_score:
                best_score = score
                best_child = child
        return best_child

    def expand(self, player_id):
        if self.untried_actions is None or len(self.untried_actions) == 0:
            return self
        action = self.untried_actions.pop()
        new_state = self.state.copy()
        try:
            _simulate_step_mut(new_state, {player_id: action})
        except Exception:
            import traceback
            traceback.print_exc()
            return self
        child = MCTSNode(new_state, parent=self, action=action)
        self.children.append(child)
        return child

def agent(obs, config=None):
    print(f"DEBUG agent called step={obs.get('step', -1)}", file=sys.stderr, flush=True)
    start_time = time.time()
    _init_jax()  # Lazy JAX init (no-op after first call; safe in subprocess workers)


    # [Phase 8] Adaptive Strategy Injection
    # Scale urgency based on global opponent profile
    avg_hardness = CONFIG['DEFAULT_HARDNESS']
    # Note: If environment provides names, we use them. Otherwise default.
    expansion_scale = 1.0 + (avg_hardness - 0.5) * 2.0
    CONFIG['EXPANSION_WEIGHT'] = 2.0 * expansion_scale

    try:
        player_id = int(obs.get("player", 0)) if isinstance(obs, dict) else int(getattr(obs, "player", 0))
        initial_state = GameState.from_obs(obs)

        # [Pro-Insight #693471] Turn 0 Precomputation (60s Warmup window)
        try:
            _FM = forward_model
        except (ImportError, NameError):
            class GlobalsNamespace:
                def __getattr__(self, name): return globals()[name]
                def __setattr__(self, name, value): globals()[name] = value
            _FM = GlobalsNamespace()
        # Reset table on Turn 0 to handle multiple seeds in benchmark
        if initial_state.step == 0:
            _FM.IS_TABLE_READY = False

        if not _FM.IS_TABLE_READY and len(initial_state.planets) > 0:
            p_nb, _, _ = initial_state.to_nb_arrays()
            _FM.nb_precompute_planet_positions(p_nb, initial_state.angular_velocity, _FM.PLANET_POS_TABLE)
            _FM.IS_TABLE_READY = True
            # [Telemetry] Log engine status once

        root = MCTSNode(initial_state)
        iters = 0
        num_samples = 32
        # -----------------------------------------------------------------------
        # PERSISTENT BUFFERS (Avoid re-allocation + handle variable planet counts)
        # -----------------------------------------------------------------------
        n_planets = len(initial_state.planets)
        max_fleets = 200
        p_batch = np.zeros((num_samples, 100, 10), dtype=np.float64)
        f_batch = np.zeros((num_samples, max_fleets, 8), dtype=np.float64)
        m_batch = np.zeros((num_samples, 4), dtype=np.float64)

        total_sim_steps = 0 # For SPS Tracking
        # -----------------------------------------------------------------------
        # DYNAMIC WEIGHT SYNCHRONIZATION (For Personas & Evolution)
        # -----------------------------------------------------------------------
        conf = config if config else {}
        w_prod = conf.get("PROD_WEIGHT", PROD_WEIGHT)
        w_ship = conf.get("SHIP_WEIGHT", SHIP_WEIGHT)
        w_threat = conf.get("THREAT_WEIGHT", THREAT_WEIGHT)
        w_expand = conf.get("EARLY_EXPAND_BONUS", EARLY_EXPAND_BONUS)
        w_urgency = conf.get("URGENCY_WEIGHT", URGENCY_ALPHA)
        w_leader = conf.get("LEADER_PENALTY", LEADER_PENALTY)
        w_centrality = conf.get("CENTRALITY_WEIGHT", CENTRALITY_WEIGHT)
        w_peace = conf.get("PEACE_WEIGHT", LEAD_TARGETING_PEACE_WEIGHT)

        weights = np.array([
            w_prod, w_ship, w_threat,
            w_expand, w_urgency, 0.5, # intent_threshold
            w_leader, w_centrality, 1.1, w_peace
        ], dtype=np.float64)

        while time.time() - start_time < SIM_TIME_LIMIT:
            iters += 1
            node = root
            # 1. SELECT
            while node.children and not is_terminal(node.state):
                limit = max(1.0, 2.0 * (node.visits ** 0.5))
                if len(node.children) < limit and node.untried_actions:
                    break
                node = node.select_child()

            # 2. EXPAND
            if not is_terminal(node.state):
                if node.untried_actions is None:
                    node.untried_actions = get_macro_candidates(node.state, player_id)
                    random.shuffle(node.untried_actions)

                if node.untried_actions:
                    node = node.expand(player_id)

            # 3. SIMULATE
            p_nb, f_nb, m_nb = node.state.to_nb_arrays(max_fleets=max_fleets)

            for b in range(num_samples):
                p_batch[b, :, :] = p_nb.copy()
                f_batch[b, :, :] = f_nb.copy()
                m_batch[b, :] = m_nb.copy()

            # Always use Numba adversarial rollouts for correct opponent modeling.
            # JAX physics-only rollouts don't model opponent greedy policy,
            # which causes wrong MCTS value estimates.
            nb_simulate_batch(p_batch, f_batch, m_batch, ROLLOUT_STEPS, adversarial=True)
            total_sim_steps += num_samples * ROLLOUT_STEPS

            # Use JAX for fast batch evaluation if available, else fall back to Numba
            if _JAX_ENGINE is not None:
                try:
                    pos_tbl = getattr(_FM, "PLANET_POS_TABLE", np.zeros((100, 501, 2), dtype=np.float64))
                    rewards_jax = _JAX_ENGINE.jax_evaluate_batch(
                        p_batch, f_batch, player_id, m_batch[:, 1], weights
                    )
                    reward = float(np.mean(np.array(rewards_jax))) / 5000.0
                except Exception as e:
                    sys.stderr.write(f"JAX eval fallback: {e}\n")
                    rewards = nb_evaluate_batch(p_batch, f_batch, player_id, m_batch[:, 1], weights)
                    reward = np.mean(rewards) / 5000.0
            else:
                rewards = nb_evaluate_batch(p_batch, f_batch, player_id, m_batch[:, 1], weights)
                reward = np.mean(rewards) / 5000.0

            # 4. BACKPROPAGATE
            curr = node
            while curr:
                curr.visits += 1
                curr.value += reward
                curr = curr.parent

        if iters > 0:
            elapsed = time.time() - start_time

        if not root.children: return []
        best_child = max(root.children, key=lambda c: c.visits)

        # [Pro-Insight #693471] Performance Tracking
        elapsed = time.time() - start_time
        sps = total_sim_steps / elapsed if elapsed > 0 else 0
        if initial_state.step % 10 == 0:
            print(f"DEBUG iters={iters} SPS={int(sps)} iters/s={int(iters/elapsed)}")

        return best_child.action
    except Exception:
        traceback.print_exc()
        return []

# Final Warmup Trigger
try:
    nb_warmup()
except: pass